import { ExecutionError } from "../error.js";
import { resolveRuntimeInput } from "../runtime-input.js";
import type { HandlerOptions } from "../types.js";
import type { CapabilityContext } from "./context.js";
import { createCapabilityContext } from "./context.js";
import { writeError, writeOutput } from "./output.js";

/**
 * A single incoming webhook request.
 */
export interface WebhookEvent {
	/**
	 * Unique ID for this webhook delivery, stable across retries.
	 * Best-effort idempotency key — prefer using the webhook provider's
	 * own delivery/event ID when available, since providers may redeliver
	 * the same event with a new deliveryId.
	 */
	deliveryId: string;
	/**
	 * The parsed JSON body of the incoming request, or an empty object if
	 * the body is not valid JSON.
	 */
	body: Record<string, unknown>;
	/**
	 * The raw request body as a string, useful for signature verification.
	 */
	rawBody: string;
	/**
	 * The HTTP headers from the incoming request
	 */
	headers: Record<string, string>;
	/**
	 * The HTTP method of the incoming request (e.g. "POST")
	 */
	method: string;
}

/**
 * Throw this error from your webhook execute handler to signal that
 * signature verification failed. After 5 consecutive verification
 * failures, the platform will short-circuit and reject all incoming
 * requests for this webhook without executing the handler.
 *
 * @example
 * ```ts
 * worker.webhook("onGithubPush", {
 *   title: "GitHub Push",
 *   description: "Handles GitHub push events",
 *   execute: async (events) => {
 *     const secret = process.env.GITHUB_WEBHOOK_SECRET;
 *     if (!secret) {
 *       throw new WebhookVerificationError("GITHUB_WEBHOOK_SECRET not set");
 *     }
 *     for (const event of events) {
 *       if (!verifyGitHubSignature(event.rawBody, event.headers, secret)) {
 *         throw new WebhookVerificationError("Invalid GitHub signature");
 *       }
 *       // ... handle verified event
 *     }
 *   },
 * });
 * ```
 */
export class WebhookVerificationError extends ExecutionError {
	constructor(cause?: unknown) {
		super(cause ?? "Webhook signature verification failed");
		this.name = "WebhookVerificationError";
	}
}

/**
 * The inbound HTTP request passed to a webhook verify handler.
 */
export interface WebhookVerifyRequest {
	/** Uppercase HTTP method. Deliveries are POSTs; GET/HEAD cover challenge probes. */
	method: "GET" | "HEAD" | "POST";
	/** The full webhook URL as received. */
	url: string;
	/** Query string parameters. */
	query: Record<string, string>;
	/** Request headers with lowercased names. */
	headers: Record<string, string>;
	/** Raw request body. Empty string for bodyless methods like GET and HEAD. */
	rawBody: string;
}

/**
 * The HTTP response a verify handler produces. Delivery is derived from the
 * status: a 2xx response is enqueued for the async `execute` handler, while a
 * 4xx rejection is returned to the provider without running `execute`.
 */
export interface WebhookVerifyResponse {
	/** Response status code. Only 2xx and 4xx statuses are allowed. */
	status: number;
	/** Optional response body, at most 8KB. */
	body?: string;
	/** Response content type. Defaults to "text/plain". */
	contentType?: "application/json" | "text/plain";
}

/**
 * A webhook verify handler. Runs synchronously at Notion's webhook ingress,
 * before the HTTP response is sent, in the worker's own sandbox — the same
 * runtime as `execute`, with the full Node.js standard library. Read signing
 * secrets from `process.env` and use `node:crypto` for signature checks.
 *
 * Keep it fast: the run must fit a small wall-clock budget (a few seconds,
 * including sandbox startup), so avoid network calls — including
 * `context.notion` API calls, which typically won't fit the budget.
 */
export type WebhookVerifyHandler = (
	request: WebhookVerifyRequest,
	context: CapabilityContext,
) => WebhookVerifyResponse | Promise<WebhookVerifyResponse>;

/**
 * A verify invocation as dispatched by the platform: a single `request`
 * object rather than the events array an execute invocation carries.
 */
export interface WebhookVerifyInvocation {
	request: WebhookVerifyRequest;
}

/**
 * Configuration for a webhook capability
 */
export interface WebhookConfiguration {
	/**
	 * Title of the webhook - shown in the UI when viewing webhooks
	 */
	title: string;

	/**
	 * Description of what this webhook does - shown in the UI
	 */
	description: string;

	/**
	 * Optional synchronous verification handler, run at Notion's webhook
	 * ingress before the HTTP response is sent. Use it for providers that
	 * require a synchronous verification response: signature checks with
	 * specific status codes, challenge echoes, or handshake requests.
	 *
	 * The handler controls the HTTP response, and a 2xx status enqueues the
	 * request for `execute`, including successful challenge requests. The
	 * `execute` handler must ignore challenge-only payloads. `verify` runs in
	 * the worker's own sandbox with full Node.js — read secrets from
	 * `process.env` and use `node:crypto` for signature checks. Like `execute`,
	 * it receives the capability context as its second argument.
	 *
	 * Without `verify`, the webhook keeps the current behavior: every request
	 * is accepted with `202` and processed asynchronously.
	 */
	verify?: WebhookVerifyHandler;

	/**
	 * The function that executes when the webhook is triggered.
	 * Receives an array of events (currently always a single event,
	 * but may be batched in the future).
	 *
	 * To signal a verification failure, throw a `WebhookVerificationError`.
	 * After 5 consecutive verification failures, the platform will
	 * short-circuit and stop executing the handler.
	 *
	 * @param events - The incoming webhook events
	 * @param context - The capability execution context (Notion client, etc.)
	 * @returns A promise that resolves when the webhook processing completes
	 */
	execute: (events: WebhookEvent[], context: CapabilityContext) => Promise<void> | void;
}

export type WebhookCapability = ReturnType<typeof createWebhookCapability>;

export function createWebhookCapability(key: string, config: WebhookConfiguration) {
	return {
		_tag: "webhook" as const,
		key,
		config: {
			title: config.title,
			description: config.description,
			// The manifest only records that a verify handler exists; the handler
			// itself ships in the worker bundle and runs via a verify invocation.
			...(config.verify !== undefined ? { hasVerify: true } : {}),
		},
		async handler(
			input: WebhookEvent[] | WebhookVerifyInvocation,
			options?: HandlerOptions,
		): Promise<{ status: "success" } | WebhookVerifyResponse | undefined> {
			try {
				input = await resolveRuntimeInput(input);

				if (isVerifyInvocation(input)) {
					if (config.verify === undefined) {
						throw new ExecutionError(
							`Webhook "${key}" received a verify request but does not declare a verify handler`,
						);
					}
					const response = await config.verify(input.request, createCapabilityContext("webhook"));

					if (options?.concreteOutput) {
						return response;
					}
					writeOutput({ _tag: "success", value: response });
					return undefined;
				}

				const capabilityContext = createCapabilityContext("webhook");
				await config.execute(input, capabilityContext);

				if (options?.concreteOutput) {
					return { status: "success" };
				} else {
					writeOutput({ _tag: "success", value: { status: "success" } });
				}
			} catch (err) {
				const error = err instanceof ExecutionError ? err : new ExecutionError(err);

				if (!options?.concreteOutput) {
					writeError(err);
					writeOutput({
						_tag: "error",
						error: {
							name: error.name,
							message: error.message,
							trace: error.stack,
						},
					});
				}

				throw error;
			}
		},
	};
}

/**
 * Whether an invocation is the platform's synchronous verify dispatch. The
 * platform sends execute invocations as an events array and verify
 * invocations as a `{ request }` object, so the shape disambiguates.
 */
function isVerifyInvocation(
	input: WebhookEvent[] | WebhookVerifyInvocation,
): input is WebhookVerifyInvocation {
	return !Array.isArray(input) && typeof input === "object" && input !== null && "request" in input;
}
